fn handle_query(bin: &str, args: Vec<String>) {
    // Similar to eval but deprecated warning
    // args: [OPTIONS] <INPUT> <SELECTOR>
    let mut input: Option<String> = None;
    let mut selector: Option<String> = None;
    let mut field: Option<String> = None;
    let mut one = false;
    let mut format = "json".to_string();
    let mut pretty = false;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a=="--field" {
            if i+1 < args.len() { field=Some(args[i+1].clone()); i+=2; } else { i+=1; }
        } else if a.starts_with("--field=") {
            field=Some(a.splitn(2,'=').nth(1).unwrap().to_string());
            i+=1;
        } else if a=="--one" { one=true; i+=1; }
        else if a=="--pretty" { pretty=true; i+=1; }
        else if a=="--format" {
            if i+1 < args.len() { format=args[i+1].clone(); i+=2; } else { i+=1; }
        } else if a.starts_with("--format=") {
            format=a.splitn(2,'=').nth(1).unwrap().to_string();
            i+=1;
        } else if a.starts_with('-') {
            // other options with values
            if ["--target","--root","--input","--font-path","--package-path","--package-cache-path","--creation-timestamp","--jobs","--features","--diagnostic-format"].iter().any(|p| a==*p || a.starts_with(&format!("{}=",p))) {
                if !a.contains('=') && i+1<args.len() { i+=2; } else { i+=1; }
            } else if ["-j"].contains(&a.as_str()) { i+=2; }
            else if ["--ignore-system-fonts","--ignore-embedded-fonts"].contains(&a.as_str()) { i+=1; }
            else { i+=1; }
        } else {
            if input.is_none() { input=Some(a.clone()); }
            else if selector.is_none() { selector=Some(a.clone()); }
            i+=1;
        }
    }
    if input.is_none() || selector.is_none() {
        eprintln!("error: the following required arguments were not provided:");
        if input.is_none() { eprintln!("  <INPUT>"); }
        if selector.is_none() { eprintln!("  <SELECTOR>"); }
        eprintln!();
        eprintln!("Usage: {bin} query <INPUT> <SELECTOR>", bin=bin);
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }
    let input_str = input.unwrap();
    let selector_str = selector.unwrap();

    // Check file exists
    if input_str != "-" && !Path::new(&input_str).exists() {
        eprintln!("error: input file not found (searched at {})", input_str);
        process::exit(1);
    }

    // Parse file for metadata as before
    let content = if input_str=="-" {
        // read stdin
        use std::io::Read;
        let mut buf = String::new();
        std::io::stdin().read_to_string(&mut buf).unwrap_or(0);
        buf
    } else {
        fs::read_to_string(&input_str).unwrap_or(String::new())
    };

    let mut results: Vec<serde_json::Value> = Vec::new();
    let mut idx = 0;
    while let Some(pos) = content[idx..].find("#metadata") {
        let start = idx+pos;
        if let Some(paren_start) = content[start..].find('(') {
            let ps = start+paren_start+1;
            if let Some(paren_end) = content[ps..].find(')') {
                let pe = ps+paren_end;
                let inside = &content[ps..pe];
                let value = inside.trim().trim_matches('"').trim_matches('\'').to_string();
                let after = &content[pe..];
                if let Some(lt) = after.find('<') {
                    if let Some(gt) = after[lt..].find('>') {
                        let label = &after[lt..lt+gt+1];
                        let mut obj = serde_json::Map::new();
                        obj.insert("func".to_string(), serde_json::Value::String("metadata".to_string()));
                        obj.insert("value".to_string(), serde_json::Value::String(value.clone()));
                        obj.insert("label".to_string(), serde_json::Value::String(label.to_string()));
                        // Check selector
                        let sel = selector_str.trim();
                        if sel=="metadata" || sel==label {
                            results.push(serde_json::Value::Object(obj));
                        } else if sel.starts_with('<') && sel.ends_with('>') && sel==label {
                            results.push(serde_json::Value::Object(obj));
                        }
                    }
                }
                idx = pe+1;
                continue;
            }
        }
        idx = start+1;
        if idx>=content.len() { break; }
    }

    // Handle --field
    let mut final_vals: Vec<serde_json::Value> = Vec::new();
    if let Some(f) = field {
        for r in results {
            if let Some(obj) = r.as_object() {
                if let Some(v) = obj.get(&f) {
                    final_vals.push(v.clone());
                }
            }
        }
    } else {
        final_vals = results;
    }

    // Handle --one
    if one {
        if final_vals.len()!=1 {
            eprintln!("error: expected exactly one element, found {}", final_vals.len());
            process::exit(1);
        }
        // one element, output that element (not array)
        let val = final_vals[0].clone();
        match format.as_str() {
            "json" => {
                if pretty {
                    println!("{}", serde_json::to_string_pretty(&val).unwrap());
                } else {
                    println!("{}", serde_json::to_string(&val).unwrap());
                }
            },
            "yaml" => {
                println!("{}", serde_yaml::to_string(&val).unwrap());
            },
            _ => {}
        }
        // print warning after? In original, warning printed to stderr after json? Actually earlier we saw warning after json on stderr? Let's check: query output included warning on stderr after json? The earlier test showed json then warning on next line? Actually the warning was printed to stderr but appeared after stdout? In original, we saw json then warning line. We need to print warning to stderr.
        eprintln!("warning: the `typst query` subcommand is deprecated");
        eprintln!(" = hint: use `typst eval 'query({}).first()' --in {}` instead", selector_str, input_str);
        return;
    }

    // Output
    match format.as_str() {
        "json" => {
            let arr = serde_json::Value::Array(final_vals.clone());
            if pretty {
                println!("{}", serde_json::to_string_pretty(&arr).unwrap());
            } else {
                println!("{}", serde_json::to_string(&arr).unwrap());
            }
        },
        "yaml" => {
            println!("{}", serde_yaml::to_string(&serde_json::Value::Array(final_vals.clone())).unwrap());
        },
        _ => {}
    }
    eprintln!("warning: the `typst query` subcommand is deprecated");
    // Provide hint
    let hint_selector = if selector_str=="metadata" { "metadata".to_string() } else { selector_str.clone() };
    let hint = if field.is_some() {
        format!("query({}).map(it => it.{})", hint_selector, field.unwrap())
    } else {
        format!("query({})", hint_selector)
    };
    eprintln!(" = hint: use `typst eval '{}' --in {}` instead", hint, input_str);
}

