fn print_with_bin(template: &str, bin: &str) {
    // The captured help files use "executable" as bin name. Replace with actual bin.
    // In original, usage shows bin name exactly as executed (e.g., "executable"), so we need to replace "executable" with bin.
    // Our template currently contains "executable" because we captured from ./executable.
    // So replace occurrences of "executable" with bin.
    let out = template.replace("executable", bin);
    print!("{}", out);
}
