fn handle_compile(bin: &str, args: Vec<String>) {
    if args.is_empty() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <INPUT>");
        eprintln!();
        eprintln!("Usage: {} compile <INPUT> [OUTPUT]", bin);
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }
    let mut input: Option<String> = None;
    let mut output: Option<String> = None;
    let mut format: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "-f" || a == "--format" {
            if i+1 < args.len() {
                let v = args[i+1].clone();
                if !["pdf","png","svg","html"].contains(&v.as_str()) {
                    // compute similar
                    let similar = suggest_similar(&v, &["pdf","png","svg","html"]);
                    eprintln!("error: invalid value '{}' for '--format <FORMAT>'", v);
                    eprintln!("  [possible values: pdf, png, svg, html]");
                    eprintln!();
                    if let Some(s) = similar {
                        eprintln!("  tip: a similar value exists: '{}'", s);
                        eprintln!();
                    }
                    eprintln!("For more information, try '--help'.");
                    process::exit(2);
                }
                format = Some(v);
                i+=2;
