                    process::exit(2);
                }
                i+=2;
            } else { i+=1; }
        } else if a.starts_with("--diagnostic-format=") { i+=1; }
        else if a == "--features" {
            if i+1 < args.len() {
                let v = args[i+1].clone();
                let possible = ["html","a11y-extras"];
                // features could be comma separated? In original it accepts one at a time but can repeat.
                // For simplicity, check if any part invalid?
                i+=2;
            } else { i+=1; }
        } else if a.starts_with("--features=") { i+=1; }
        else if a.starts_with('-') {
            // known flags
            let known_with_val = ["--root","--input","--font-path","--package-path","--package-cache-path","--creation-timestamp","--pages","--ppi","--deps","--jobs","--open","--timings","--port","--format","--pdf-standard","--deps-format","--diagnostic-format","--features"];
            let known_bool = ["--ignore-system-fonts","--ignore-embedded-fonts","--no-pdf-tags","--no-serve","--no-reload"];
            let mut handled = false;
            for k in known_with_val.iter() {
                if a==*k || a.starts_with(&format!("{}=",k)) {
                    if !a.contains('=') {
                        if i+1 < args.len() && !args[i+1].starts_with('-') { i+=1; }
                    }
                    handled = true;
                    break;
                }
            }
            if handled { i+=1; continue; }
            for k in known_bool.iter() {
                if a==*k { handled=true; break; }
