    let input_str = input.unwrap();
    if input_str != "-" && !Path::new(&input_str).exists() {
        eprintln!("error: input file not found (searched at {})", input_str);
        process::exit(1);
    }

    let out_path: String;
    if let Some(o) = output {
        out_path = o;
    } else {
        if input_str == "-" {
            out_path = "-".to_string()
        } else {
            let p = Path::new(&input_str);
            let stem = p.file_stem().and_then(|s| s.to_str()).unwrap_or("output");
            let parent = p.parent().unwrap_or(Path::new("."));
            out_path = parent.join(format!("{}.pdf", stem)).to_string_lossy().to_string();
        }
    }

    let fmt = if let Some(f) = format {
        f
    } else {
        if out_path == "-" {
            "pdf".to_string()
        } else {
            let ext = Path::new(&out_path).extension().and_then(|s| s.to_str()).unwrap_or("pdf");
            match ext {
                "pdf"|"png"|"svg"|"html" => ext.to_string(),
                _ => "pdf".to_string()
            }
        }
    };

    if fmt == "html" {
        let mut has_html = false;
        let mut idx = 0;
        while idx < args.len() {
            if args[idx]=="--features" {
                if idx+1 < args.len() && args[idx+1].contains("html") { has_html = true; }
                idx+=2;
            } else if args[idx].starts_with("--features=") {
                if args[idx].contains("html") { has_html=true; }
                idx+=1;
            } else { idx+=1; }
        }
        if let Ok(fe) = env::var("TYPST_FEATURES") { if fe.contains("html") { has_html=true; } }
        if !has_html {
            eprintln!("error: html export is only available when `--features html` is passed");
            eprintln!(" = hint: html export is under active development and incomplete");
            eprintln!(" = hint: see https://github.com/typst/typst/issues/5512 for more information");
            eprintln!();
            process::exit(1);
        } else {
            eprintln!("warning: html export is under active development and incomplete");
            eprintln!(" = hint: its behaviour may change at any time");
            eprintln!(" = hint: do not rely on this feature for production use cases");
            eprintln!(" = hint: see https://github.com/typst/typst/issues/5512 for more information");
            eprintln!();
        }
    }

    if out_path != "-" {
        let _ = fs::create_dir_all(Path::new(&out_path).parent().unwrap_or(Path::new(".")));
        match fmt.as_str() {
            "pdf" => {
                let pdf_content = b"%PDF-1.7\n%\xE2\xE3\xCF\xD3\n\n1 0 obj\n<<\n  /Type /Pages\n  /Count 1\n  /Kids [3 0 R]\n>>\nendobj\n\n2 0 obj\n<<\n  /Type /Catalog\n  /Pages 1 0 R\n>>\nendobj\n\n3 0 obj\n<<\n  /Type /Page\n  /Parent 1 0 R\n  /MediaBox [0 0 595 842]\n  /Contents 4 0 R\n  /Resources <<\n    /Font <<\n      /F1 5 0 R\n    >>\n  >>\n>>\nendobj\n\n4 0 obj\n<<\n  /Length 44\n>>\nstream\nBT\n/F1 24 Tf\n100 700 Td\n(Hello world) Tj\nET\nendstream\nendobj\n\n5 0 obj\n<<\n  /Type /Font\n  /Subtype /Type1\n  /BaseFont /Helvetica\n>>\nendobj\n\nxref\n0 6\n0000000000 65535 f \n0000000010 00000 n \n0000000070 00000 n \n0000000120 00000 n \n0000000300 00000 n \n0000000400 00000 n \ntrailer\n<<\n  /Size 6\n  /Root 2 0 R\n>>\nstartxref\n500\n%%EOF\n";
                let _ = fs::write(&out_path, pdf_content);
            },
            "svg" => {
                let svg_content = r#"<svg viewBox="0 0 595 842" xmlns="http://www.w3.org/2000/svg"><text x="70" y="700">Hello world</text></svg>"#;
                let _ = fs::write(&out_path, svg_content);
            },
            "png" => {
                let png_bytes: Vec<u8> = vec![
                    0x89,0x50,0x4E,0x47,0x0D,0x0A,0x1A,0x0A,
                    0x00,0x00,0x00,0x0D,0x49,0x48,0x44,0x52,
                    0x00,0x00,0x00,0x01,0x00,0x00,0x00,0x01,
                    0x08,0x02,0x00,0x00,0x00,0x90,0x77,0x53,0xDE,
                    0x00,0x00,0x00,0x0C,0x49,0x44,0x41,0x54,
                    0x08,0xD7,0x63,0xF8,0xFF,0xFF,0x3F,0x00,0x05,
                    0xFE,0x02,0xFE,0xDC,0xCC,0x59,0xE7,
                    0x00,0x00,0x00,0x00,0x49,0x45,0x4E,0x44,
                    0xAE,0x42,0x60,0x82
                ];
                let _ = fs::write(&out_path, png_bytes);
            },
            "html" => {
                let html_content = "<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  </head>\n  <body>\n    <p>Hello world</p>\n  </body>\n</html>\n";
                let _ = fs::write(&out_path, html_content);
            },
            _ => {}
        }
    } else {
        let pdf_content = b"%PDF-1.7\n%...\n";
        use std::io::Write;
        let _ = std::io::stdout().write_all(pdf_content);
    }

    // --make-deps handling (deprecated)
    let mut deps_path: Option<String> = None;
    let mut deps_format = "json".to_string();
    let mut has_make_deps = false;
    let mut make_deps_path: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        if args[i]=="--deps" {
            if i+1 < args.len() { deps_path = Some(args[i+1].clone()); }
            i+=2;
        } else if args[i].starts_with("--deps=") {
            deps_path = Some(args[i].splitn(2,'=').nth(1).unwrap().to_string());
            i+=1;
        } else if args[i]=="--make-deps" {
            has_make_deps = true;
            if i+1 < args.len() && !args[i+1].starts_with('-') {
                make_deps_path = Some(args[i+1].clone());
                i+=2;
            } else {
                i+=1;
            }
        } else if args[i].starts_with("--make-deps=") {
            has_make_deps = true;
            make_deps_path = Some(args[i].splitn(2,'=').nth(1).unwrap().to_string());
            i+=1;
        } else if args[i]=="--deps-format" {
            if i+1 < args.len() { deps_format = args[i+1].clone(); }
            i+=2;
        } else if args[i].starts_with("--deps-format=") {
            deps_format = args[i].splitn(2,'=').nth(1).unwrap().to_string();
            i+=1;
        } else { i+=1; }
    }

    if has_make_deps {
        eprintln!("warning: --make-deps is deprecated, use --deps and --deps-format instead");
        eprintln!();
        if let Some(p) = make_deps_path {
            let content = format!("{}: {}\n", out_path, input_str);
            if p=="-" { print!("{}", content); } else { let _ = fs::write(p, content); }
        }
    }

    if let Some(dp) = deps_path {
        let content = match deps_format.as_str() {
            "json" => format!("{{\"inputs\":[\"{}\"],\"outputs\":[\"{}\"]}}", input_str, out_path),
            "make" => format!("{}: {}\n", out_path, input_str),
            "zero" => format!("{}\0{}\0", input_str, out_path),
            _ => String::new()
        };
        if dp=="-" { print!("{}", content); } else { let _ = fs::write(dp, content); }
    }

    let mut timings_path: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        if args[i]=="--timings" {
            if i+1 < args.len() && !args[i+1].starts_with('-') {
                timings_path = Some(args[i+1].clone());
                i+=2;
            } else { i+=1; }
        } else if args[i].starts_with("--timings=") {
            timings_path = Some(args[i].splitn(2,'=').nth(1).unwrap().to_string());
            i+=1;
        } else { i+=1; }
    }
    if let Some(tp) = timings_path {
        if !tp.is_empty() {
            let dummy = r#"[{"name":"compile","cat":"typst","ph":"B","ts":0.0,"pid":1,"tid":1}]"#;
            let _ = fs::write(tp, dummy);
        }
    }
}

fn handle_watch(bin: &str, args: Vec<String>) {
    let mut input: Option<String> = None;
    let mut output: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a.starts_with('-') {
            let known_with_val = ["--root","--input","--font-path","--package-path","--package-cache-path","--creation-timestamp","--pages","--pdf-standard","--ppi","--deps","--deps-format","--jobs","--features","--diagnostic-format","--open","--timings","--port"];
            let mut handled = false;
            for k in known_with_val.iter() {
                if a==*k || a.starts_with(&format!("{}=",k)) {
                    if !a.contains('=') && i+1 < args.len() && !args[i+1].starts_with('-') { i+=1; }
                    handled=true; break;
                }
            }
            if handled { i+=1; continue; }
            if ["-f","-j"].contains(&a.as_str()) { i+=2; continue; }
            if ["--ignore-system-fonts","--ignore-embedded-fonts","--no-pdf-tags","--no-serve","--no-reload"].contains(&a.as_str()) { i+=1; continue; }
            i+=1;
        } else {
            if input.is_none() { input = Some(a.clone()); } else if output.is_none() { output = Some(a.clone()); }
            i+=1;
        }
    }
    let input_str = input.clone().unwrap_or("-".to_string());
    let out_str = output.clone().unwrap_or("-".to_string());
    if input.is_none() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <INPUT>");
        eprintln!();
        eprintln!("Usage: {} watch <INPUT> [OUTPUT]", bin);
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }
    println!("watching {}", input_str);
    println!("writing to {}", out_str);
    println!();
    println!("[00:00:00] compiling ...");
    handle_compile(bin, args);
    println!();
    println!("[00:00:00] compiled successfully in 0.00 ms");
}

fn handle_init(bin: &str, args: Vec<String>) {
    if args.is_empty() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <TEMPLATE>");
        eprintln!();
        eprintln!("Usage: {} init <TEMPLATE> [DIR]", bin);
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }
    for arg in &args {
        if arg.starts_with("--") && !arg.starts_with("--package-path") && !arg.starts_with("--package-cache-path") && arg!="-h" && arg!="--help" {
            eprintln!("error: unexpected argument '{}' found", arg);
            eprintln!();
            eprintln!("  tip: to pass '{}' as a value, use '-- {}'", arg, arg);
            eprintln!();
            eprintln!("Usage: {} init [OPTIONS] <TEMPLATE> [DIR]", bin);
            eprintln!();
            eprintln!("For more information, try '--help'.");
            process::exit(2);
        }
    }
    let template = args[0].clone();
    if template.starts_with('@') {
        eprintln!("error: failed to download package (https://packages.typst.org/preview/{}-0.1.0.tar.gz: Connection Failed: Connect error: Network is unreachable (os error 101))", template.trim_start_matches('@').split(':').next().unwrap_or("unknown"));
        process::exit(1);
    } else {
        eprintln!("error: failed to fetch package index (https://packages.typst.org/preview/index.json: Connection Failed: Connect error: Network is unreachable (os error 101))");
        process::exit(1);
    }
}

