fn print_with_bin(template: &str, bin: &str) {
    let out = template.replace("executable", bin);
    print!("{}", out);
}

fn suggest_similar(input: &str, candidates: &[&str]) -> Option<String> {
    fn lev(a: &str, b: &str) -> usize {
        let mut dp = vec![vec![0; b.len()+1]; a.len()+1];
        for i in 0..=a.len() { dp[i][0]=i; }
        for j in 0..=b.len() { dp[0][j]=j; }
        for (i, ca) in a.chars().enumerate() {
            for (j, cb) in b.chars().enumerate() {
                let cost = if ca==cb {0} else {1};
                dp[i+1][j+1] = std::cmp::min(
                    std::cmp::min(dp[i][j+1]+1, dp[i+1][j]+1),
                    dp[i][j]+cost
                );
            }
        }
        dp[a.len()][b.len()]
    }
    let mut best: Option<(usize,String)> = None;
    for c in candidates {
        let d = lev(input, c);
        if d<=3 {
            if best.is_none() || d < best.as_ref().unwrap().0 {
                best = Some((d, c.to_string()));
            }
        }
    }
    best.map(|(_,s)| s)
}

