            }
        } else if a.starts_with("--pdf-standard=") {
            let v = a.splitn(2,'=').nth(1).unwrap().to_string();
            let possible = ["1.4","1.5","1.6","1.7","2.0","a-1b","a-1a","a-2b","a-2u","a-2a","a-3b","a-3u","a-3a","a-4","a-4f","a-4e","ua-1"];
            if !possible.contains(&v.as_str()) {
                eprintln!("error: invalid value '{}' for '--pdf-standard <PDF_STANDARD>'", v);
                eprintln!("  [possible values: 1.4, 1.5, 1.6, 1.7, 2.0, a-1b, a-1a, a-2b, a-2u, a-2a, a-3b, a-3u, a-3a, a-4, a-4f, a-4e, ua-1]");
                eprintln!();
