fn handle_completions(bin: &str, args: Vec<String>) {
    if args.is_empty() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <SHELL>");
        eprintln!();
        eprintln!("Usage: {} completions <SHELL>", bin);
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }
    if args.len()>1 {
        eprintln!("error: unexpected argument '{}' found", args[1]);
        eprintln!();
        eprintln!("Usage: {} completions <SHELL>", bin);
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }
    let shell = &args[0];
    if !["bash","elvish","fish","powershell","zsh"].contains(&shell.as_str()) {
        eprintln!("error: invalid value '{}' for '<SHELL>'", shell);
        eprintln!("  [possible values: bash, elvish, fish, powershell, zsh]");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }
    match shell.as_str() {
        "bash" => print!("{}", BASH_COMPLETION),
        "fish" => print!("{}", FISH_COMPLETION),
        "zsh" => print!("{}", ZSH_COMPLETION),
        "elvish" => print!("{}", ELVISH_COMPLETION),
        "powershell" => print!("{}", POWERSHELL_COMPLETION),
        _ => {}
    }
}

fn handle_info(bin: &str, args: Vec<String>) {
    let mut format: Option<String> = None;
    let mut pretty = false;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a=="-f" || a=="--format" {
            if i+1 < args.len() {
                let v = args[i+1].clone();
                if !["json","yaml"].contains(&v.as_str()) {
                    eprintln!("error: invalid value '{}' for '--format <FORMAT>'", v);
                    eprintln!("  [possible values: json, yaml]");
                    eprintln!();
                    eprintln!("  tip: a similar value exists: 'json'");
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
                format = Some(v);
                i+=2;
            } else {
                eprintln!("error: a value is required for '--format <FORMAT>' but none was supplied");
                eprintln!("  [possible values: json, yaml]");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
        } else if a.starts_with("--format=") {
            let v = a.splitn(2,'=').nth(1).unwrap().to_string();
            if !["json","yaml"].contains(&v.as_str()) {
                eprintln!("error: invalid value '{}' for '--format <FORMAT>'", v);
                eprintln!("  [possible values: json, yaml]");
                eprintln!();
                eprintln!("  tip: a similar value exists: 'json'");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            format = Some(v);
            i+=1;
        } else if a=="--pretty" {
            pretty=true;
            i+=1;
        } else if a.starts_with('-') {
            eprintln!("error: unexpected argument '{}' found", a);
            eprintln!();
            eprintln!("  tip: to pass '{}' as a value, use '-- {}'", a, a);
            eprintln!();
            eprintln!("Usage: {} info [OPTIONS]", bin);
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        } else {
            eprintln!("error: unexpected argument '{}' found", a);
            eprintln!();
            eprintln!("Usage: {} info [OPTIONS]", bin);
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }

    let env_vars = ["TYPST_CERT","TYPST_FEATURES","TYPST_FONT_PATHS","TYPST_IGNORE_SYSTEM_FONTS","TYPST_IGNORE_EMBEDDED_FONTS","TYPST_PACKAGE_CACHE_PATH","TYPST_PACKAGE_PATH","TYPST_ROOT","TYPST_UPDATE_BACKUP_PATH","SOURCE_DATE_EPOCH","XDG_CACHE_HOME","XDG_DATA_HOME","FONTCONFIG_FILE","OPENSSL_CONF","NO_COLOR","NO_PROXY","HTTP_PROXY","HTTPS_PROXY","ALL_PROXY"];
    let mut env_map: HashMap<String, Option<String>> = HashMap::new();
    for k in env_vars.iter() {
        env_map.insert(k.to_string(), env::var(k).ok());
    }

    let font_paths: Vec<String> = if let Some(v) = env_map.get("TYPST_FONT_PATHS").unwrap_or(&None) {
        if v.is_empty() { vec![] } else { v.split(':').map(|s| s.to_string()).collect() }
    } else { vec![] };

    let system_fonts = env_map.get("TYPST_IGNORE_SYSTEM_FONTS").unwrap_or(&None).is_none();
    let embedded_fonts = env_map.get("TYPST_IGNORE_EMBEDDED_FONTS").unwrap_or(&None).is_none();

    let package_path = if let Some(p) = env_map.get("TYPST_PACKAGE_PATH").unwrap_or(&None) {
        p.clone()
    } else if let Some(xdg) = env_map.get("XDG_DATA_HOME").unwrap_or(&None) {
        format!("{}/typst/packages", xdg)
    } else {
        let home = env::var("HOME").unwrap_or("/home/agent".to_string());
        format!("{}/.local/share/typst/packages", home)
    };
    let package_cache_path = if let Some(p) = env_map.get("TYPST_PACKAGE_CACHE_PATH").unwrap_or(&None) {
        p.clone()
    } else if let Some(xdg) = env_map.get("XDG_CACHE_HOME").unwrap_or(&None) {
        format!("{}/typst/packages", xdg)
    } else {
        let home = env::var("HOME").unwrap_or("/home/agent".to_string());
        format!("{}/.cache/typst/packages", home)
    };

    match format.as_deref() {
        Some("json") => {
            let mut env_json = serde_json::Map::new();
            for k in env_vars.iter() {
                let val = env_map.get(*k).unwrap();
                if let Some(v) = val {
                    env_json.insert(k.to_string(), serde_json::Value::String(v.clone()));
                } else {
                    env_json.insert(k.to_string(), serde_json::Value::Null);
                }
            }
            let mut obj = serde_json::Map::new();
            obj.insert("version".to_string(), serde_json::Value::String("0.14.2".to_string()));
            let mut build = serde_json::Map::new();
            build.insert("commit".to_string(), serde_json::Value::String("97ac4370f3ef5ce1dd0034d735158d7ad9d494cd".to_string()));
            let mut platform = serde_json::Map::new();
            platform.insert("os".to_string(), serde_json::Value::String("linux".to_string()));
            platform.insert("arch".to_string(), serde_json::Value::String("x86_64".to_string()));
            build.insert("platform".to_string(), serde_json::Value::Object(platform));
            let mut settings = serde_json::Map::new();
            settings.insert("self-update".to_string(), serde_json::Value::Bool(false));
            settings.insert("http-server".to_string(), serde_json::Value::Bool(true));
            build.insert("settings".to_string(), serde_json::Value::Object(settings));
            obj.insert("build".to_string(), serde_json::Value::Object(build));
            let mut features = serde_json::Map::new();
            features.insert("html".to_string(), serde_json::Value::Bool(false));
            features.insert("a11y-extras".to_string(), serde_json::Value::Bool(false));
            obj.insert("features".to_string(), serde_json::Value::Object(features));
            let mut fonts = serde_json::Map::new();
            let paths_json: Vec<serde_json::Value> = font_paths.iter().map(|p| serde_json::Value::String(p.clone())).collect();
            fonts.insert("paths".to_string(), serde_json::Value::Array(paths_json));
            fonts.insert("system".to_string(), serde_json::Value::Bool(system_fonts));
            fonts.insert("embedded".to_string(), serde_json::Value::Bool(embedded_fonts));
            obj.insert("fonts".to_string(), serde_json::Value::Object(fonts));
            let mut packages = serde_json::Map::new();
            packages.insert("package-path".to_string(), serde_json::Value::String(package_path));
            packages.insert("package-cache-path".to_string(), serde_json::Value::String(package_cache_path));
            obj.insert("packages".to_string(), serde_json::Value::Object(packages));
            obj.insert("env".to_string(), serde_json::Value::Object(env_json));
            let json_val = serde_json::Value::Object(obj);
            if pretty {
                println!("{}", serde_json::to_string_pretty(&json_val).unwrap());
            } else {
                println!("{}", serde_json::to_string(&json_val).unwrap());
            }
        },
        Some("yaml") => {
            println!("version: 0.14.2");
            println!("build:");
            println!("  commit: 97ac4370f3ef5ce1dd0034d735158d7ad9d494cd");
            println!("  platform:");
            println!("    os: linux");
            println!("    arch: x86_64");
            println!("  settings:");
            println!("    self-update: false");
            println!("    http-server: true");
            println!("features:");
            println!("  html: false");
            println!("  a11y-extras: false");
            println!("fonts:");
            if font_paths.is_empty() {
                println!("  paths: []");
            } else {
                println!("  paths:");
                for p in &font_paths {
                    println!("  - {}", p);
                }
            }
            println!("  system: {}", system_fonts);
            println!("  embedded: {}", embedded_fonts);
            println!("packages:");
            println!("  package-path: {}", package_path);
            println!("  package-cache-path: {}", package_cache_path);
            println!("env:");
            for k in env_vars.iter() {
                if let Some(v) = env_map.get(*k).unwrap() {
                    println!("  {}: {}", k, v);
                } else {
                    println!("  {}: null", k);
                }
            }
            println!();
        },
        None => {
            println!("Version 0.14.2 (97ac4370, linux on x86_64)");
            println!();
            println!("Build settings");
            println!("  self-update off (Update Typst via `typst update`)");
            println!("  http-server on  (Serve HTML via `typst watch`)");
            println!();
            println!("Features");
            println!("  html        off (Experimental HTML support)");
            println!("  a11y-extras off (Experimental accessibility additions)");
            println!();
            println!("Fonts");
            if font_paths.is_empty() {
                println!("  Custom font paths <none>");
            } else {
                println!("  Custom font paths");
                for p in &font_paths {
                    println!("    - {}", p);
                }
            }
            println!("  System fonts   {}", if system_fonts { "on" } else { "off" });
            println!("  Embedded fonts {}", if embedded_fonts { "on" } else { "off" });
            println!();
            println!("Packages");
            println!("  Package path       {}", package_path);
            println!("  Package cache path {}", package_cache_path);
            println!();
            println!("Environment variables");
            for k in env_vars.iter() {
                if let Some(v) = env_map.get(*k).unwrap() {
                    println!("  {:<28}{}", *k, v);
                } else {
                    println!("  {:<28}<unset>", *k);
                }
            }
        },
        _ => {}
    }
