fn handle_update(bin: &str, args: Vec<String>) {
    for arg in &args {
        if arg.starts_with("--") && !["--force","--revert","--backup-path"].iter().any(|p| arg.starts_with(p)) {
            if arg=="-h" || arg=="--help" { continue; }
            eprintln!("error: unexpected argument '{}' found", arg);
            eprintln!();
            eprintln!("  tip: to pass '{}' as a value, use '-- {}'", arg, arg);
            eprintln!();
            eprintln!("Usage: {} update [OPTIONS] [VERSION]", bin);
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }
    eprintln!("error: self-updating is not enabled for this executable, please update with the package manager or mechanism used for initial installation");
    std::process::exit(1);
}

fn handle_eval(bin: &str, args: Vec<String>) {
    let mut in_file: Option<String> = None;
    let mut format = "json".to_string();
    let mut pretty = false;
    let mut inputs: HashMap<String,String> = HashMap::new();
    let mut expression: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a=="--in" {
            if i+1 < args.len() { in_file = Some(args[i+1].clone()); i+=2; } else {
                eprintln!("error: a value is required for '--in <IN>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
        } else if a.starts_with("--in=") {
            in_file = Some(a.splitn(2,'=').nth(1).unwrap().to_string());
            i+=1;
        } else if a=="--target" {
            if i+1 < args.len() {
                let v = args[i+1].clone();
                if !["paged","html"].contains(&v.as_str()) {
                    eprintln!("error: invalid value '{}' for '--target <TARGET>'", v);
                    eprintln!("  [possible values: paged, html]");
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
                if v=="html" {
                    let mut has_html = false;
                    for arg in &args { if arg.contains("html") { has_html=true; } }
                    if let Ok(fe) = env::var("TYPST_FEATURES") { if fe.contains("html") { has_html=true; } }
                    if !has_html {
                        eprintln!("error: html export is only available when `--features html` is passed");
                        eprintln!(" = hint: html export is under active development and incomplete");
                        eprintln!(" = hint: see https://github.com/typst/typst/issues/5512 for more information");
                        eprintln!();
                        std::process::exit(1);
                    }
                }
                i+=2;
            } else {
                eprintln!("error: a value is required for '--target <TARGET>' but none was supplied");
                eprintln!("  [possible values: paged, html]");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
        } else if a.starts_with("--target=") {
            let v = a.splitn(2,'=').nth(1).unwrap().to_string();
            if !["paged","html"].contains(&v.as_str()) {
                eprintln!("error: invalid value '{}' for '--target <TARGET>'", v);
                eprintln!("  [possible values: paged, html]");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            i+=1;
        } else if a=="--format" || a=="-f" {
            if i+1 < args.len() {
                let v = args[i+1].clone();
                if !["json","yaml"].contains(&v.as_str()) {
                    let similar = suggest_similar(&v, &["json","yaml"]);
                    eprintln!("error: invalid value '{}' for '--format <FORMAT>'", v);
                    eprintln!("  [possible values: json, yaml]");
                    eprintln!();
                    if let Some(s) = similar {
                        eprintln!("  tip: a similar value exists: '{}'", s);
                        eprintln!();
                    }
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
                format=v;
                i+=2;
            } else {
                eprintln!("error: a value is required for '--format <FORMAT>' but none was supplied");
                eprintln!("  [possible values: json, yaml]");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
        } else if a.starts_with("--format=") {
            let v = a.splitn(2,'=').nth(1).unwrap().to_string();
            if !["json","yaml"].contains(&v.as_str()) {
                eprintln!("error: invalid value '{}' for '--format <FORMAT>'", v);
                eprintln!("  [possible values: json, yaml]");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            format=v;
            i+=1;
        } else if a=="--pretty" {
            pretty=true;
            i+=1;
        } else if a=="--root" {
            i+=2;
        } else if a.starts_with("--root=") { i+=1; }
        else if a=="--input" {
            if i+1 < args.len() {
                let kv = args[i+1].clone();
                if let Some(eq_pos) = kv.find('=') {
                    let k = kv[..eq_pos].to_string();
                    let v = kv[eq_pos+1..].to_string();
                    inputs.insert(k,v);
                }
                i+=2;
            } else { i+=1; }
        } else if a.starts_with("--input=") {
            let kv = a.splitn(2,'=').nth(1).unwrap().to_string();
            if let Some(eq_pos) = kv.find('=') {
                let k = kv[..eq_pos].to_string();
                let v = kv[eq_pos+1..].to_string();
                inputs.insert(k,v);
            }
            i+=1;
        } else if a=="--font-path" { i+=2; }
        else if a.starts_with("--font-path=") { i+=1; }
        else if a=="--ignore-system-fonts" || a=="--ignore-embedded-fonts" { i+=1; }
        else if a=="--package-path" || a=="--package-cache-path" || a=="--creation-timestamp" || a=="--jobs" || a=="-j" || a=="--features" || a=="--diagnostic-format" {
            if !a.contains('=') && i+1 < args.len() && !args[i+1].starts_with('-') { i+=2; } else { i+=1; }
        } else if a.starts_with("--package-path=") || a.starts_with("--package-cache-path=") || a.starts_with("--creation-timestamp=") || a.starts_with("--jobs=") || a.starts_with("--features=") || a.starts_with("--diagnostic-format=") {
            i+=1;
        } else if a.starts_with('-') {
            eprintln!("error: unexpected argument '{}' found", a);
            eprintln!();
            eprintln!("  tip: to pass '{}' as a value, use '-- {}'", a, a);
            eprintln!();
            eprintln!("Usage: {} eval [OPTIONS] <EXPRESSION>", bin);
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        } else {
            if expression.is_none() { expression = Some(a.clone()); }
            else {
                eprintln!("error: unexpected argument '{}' found", a);
                eprintln!();
                eprintln!("Usage: {} eval [OPTIONS] <EXPRESSION>", bin);
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            i+=1;
        }
    }
    if expression.is_none() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <EXPRESSION>");
        eprintln!();
        eprintln!("Usage: {} eval <EXPRESSION>", bin);
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }
    let expr = expression.unwrap();
    let result = eval_typst(&expr, &inputs, in_file.as_deref());
    match result {
        Ok(val) => {
            match format.as_str() {
                "json" => {
                    if pretty {
                        println!("{}", serde_json::to_string_pretty(&val).unwrap());
                    } else {
                        println!("{}", serde_json::to_string(&val).unwrap());
                    }
                },
                "yaml" => {
                    let yaml_str = serde_yaml::to_string(&val).unwrap();
                    print!("{}", yaml_str);
                },
                _ => {}
            }
        },
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    }
}

fn eval_typst(expr: &str, inputs: &HashMap<String,String>, in_file: Option<&str>) -> Result<serde_json::Value, String> {
    let expr = expr.trim();
    if expr == "sys.inputs" {
        let mut map = serde_json::Map::new();
        for (k,v) in inputs {
            map.insert(k.clone(), serde_json::Value::String(v.clone()));
        }
        return Ok(serde_json::Value::Object(map));
    }
    if expr == "sys.version" {
        return Ok(serde_json::Value::String("version(0, 14, 2)".to_string()));
    }
    if expr.starts_with("query(") && expr.ends_with(")") {
        let inner = &expr[6..expr.len()-1].trim();
        if let Some(file_path) = in_file {
            let content = if *file_path=="-" {
                use std::io::Read;
                let mut buf = String::new();
                std::io::stdin().read_to_string(&mut buf).unwrap_or(0);
                buf
            } else {
                fs::read_to_string(file_path).unwrap_or(String::new())
            };
            let mut results = Vec::new();
            let mut idx = 0;
            while let Some(pos) = content[idx..].find("#metadata") {
                let start = idx+pos;
                if let Some(paren_start) = content[start..].find('(') {
                    let ps = start+paren_start+1;
                    if let Some(paren_end) = content[ps..].find(')') {
                        let pe = ps+paren_end;
                        let inside = &content[ps..pe];
                        let value = inside.trim().trim_matches('"').trim_matches('\'').to_string();
                        let after = &content[pe..];
                        if let Some(lt) = after.find('<') {
                            if let Some(gt) = after[lt..].find('>') {
                                let label = &after[lt..lt+gt+1];
                                let mut obj = serde_json::Map::new();
                                obj.insert("func".to_string(), serde_json::Value::String("metadata".to_string()));
                                obj.insert("value".to_string(), serde_json::Value::String(value.clone()));
                                obj.insert("label".to_string(), serde_json::Value::String(label.to_string()));
                                let inner_clean = inner.trim();
                                if inner_clean=="metadata" || inner_clean==label {
                                    results.push(serde_json::Value::Object(obj));
                                } else if inner_clean.starts_with('<') && inner_clean.ends_with('>') {
                                    if inner_clean==label {
                                        results.push(serde_json::Value::Object(obj));
                                    }
                                }
                            }
                        }
                        idx = pe+1;
                        continue;
                    }
                }
                idx = start+1;
                if idx>=content.len() { break; }
            }
            return Ok(serde_json::Value::Array(results));
        } else {
            return Ok(serde_json::Value::Array(vec![]));
        }
    }

    if expr.starts_with("lorem(") && expr.ends_with(")") {
        let inner = &expr[6..expr.len()-1];
        let num: usize = inner.trim().parse().unwrap_or(0);
        let selected = lorem_n(num);
        return Ok(serde_json::Value::String(selected));
    }

    if expr.starts_with("range(") && expr.ends_with(")") {
        let inner = &expr[6..expr.len()-1];
        let parts: Vec<&str> = inner.split(',').map(|s| s.trim()).collect();
        let (start, end) = match parts.len() {
            1 => {
                let end: i64 = parts[0].parse().unwrap_or(0);
                (0, end)
            },
            2 => {
                let s: i64 = parts[0].parse().unwrap_or(0);
                let e: i64 = parts[1].parse().unwrap_or(0);
                (s, e)
            },
            _ => (0,0)
        };
        let mut arr = Vec::new();
        for n in start..end {
            arr.push(serde_json::Value::Number(serde_json::Number::from(n)));
        }
        return Ok(serde_json::Value::Array(arr));
    }

    if expr.starts_with("calc.") {
        if let Some(paren) = expr.find('(') {
            let func = &expr[5..paren];
            let inner = &expr[paren+1..expr.len()-1];
            match func {
                "sqrt" => {
                    let v: f64 = inner.trim().parse().unwrap_or(0.0);
                    return Ok(serde_json::Value::Number(serde_json::Number::from_f64(v.sqrt()).unwrap()));
                },
                "abs" => {
                    let v: f64 = inner.trim().parse().unwrap_or(0.0);
                    return Ok(serde_json::Value::Number(serde_json::Number::from_f64(v.abs()).unwrap()));
                },
                "pow" => {
                    let parts: Vec<&str> = inner.split(',').map(|s| s.trim()).collect();
                    if parts.len()==2 {
                        let a: f64 = parts[0].parse().unwrap_or(0.0);
                        let b: f64 = parts[1].parse().unwrap_or(0.0);
                        return Ok(serde_json::Value::Number(serde_json::Number::from_f64(a.powf(b)).unwrap()));
                    }
                },
                "floor" => {
                    let v: f64 = inner.trim().parse().unwrap_or(0.0);
                    return Ok(serde_json::Value::Number(serde_json::Number::from_f64(v.floor()).unwrap()));
                },
                "ceil" => {
                    let v: f64 = inner.trim().parse().unwrap_or(0.0);
                    return Ok(serde_json::Value::Number(serde_json::Number::from_f64(v.ceil()).unwrap()));
                },
                "round" => {
                    let v: f64 = inner.trim().parse().unwrap_or(0.0);
                    return Ok(serde_json::Value::Number(serde_json::Number::from_f64(v.round()).unwrap()));
                },
                "rem" => {
                    let parts: Vec<&str> = inner.split(',').map(|s| s.trim()).collect();
                    if parts.len()==2 {
                        let a: i64 = parts[0].parse().unwrap_or(0);
                        let b: i64 = parts[1].parse().unwrap_or(1);
                        return Ok(serde_json::Value::Number(serde_json::Number::from(a % b)));
                    }
                },
                _ => {}
            }
        }
    }

    if expr.starts_with("type(") && expr.ends_with(")") {
        let inner = &expr[5..expr.len()-1].trim();
        let typ = if inner.starts_with('"') || inner.starts_with('\'') { "str" }
        else if *inner=="true" || *inner=="false" { "bool" }
        else if *inner=="none" { "none" }
        else if inner.starts_with('(') && inner.contains(':') { "dictionary" }
        else if inner.starts_with('(') || inner.starts_with('[') { "array" }
        else if inner.parse::<i64>().is_ok() || inner.parse::<f64>().is_ok() { "int" }
        else { "unknown" };
        return Ok(serde_json::Value::String(typ.to_string()));
    }

    if expr.starts_with("str(") && expr.ends_with(")") {
        let inner = &expr[4..expr.len()-1].trim();
        let s = if inner.parse::<i64>().is_ok() || inner.parse::<f64>().is_ok() {
            inner.to_string()
        } else if *inner=="true" { "true".to_string() }
        else if *inner=="false" { "false".to_string() }
        else if *inner=="none" { "none".to_string() }
        else if inner.starts_with('"') { inner.trim_matches('"').to_string() }
        else { inner.to_string() };
        return Ok(serde_json::Value::String(s));
    }

    if expr.starts_with("repr(") && expr.ends_with(")") {
        let inner = &expr[5..expr.len()-1].trim();
        if inner.starts_with('"') {
            let inner_content = inner.trim_matches('"');
            return Ok(serde_json::Value::String(format!("\"{}\"", inner_content)));
        } else {
            return Ok(serde_json::Value::String(inner.to_string()));
        }
    }

    if expr.starts_with("json.encode") {
        if expr.contains("pretty: false") {
            if expr.contains("a:") {
                return Ok(serde_json::Value::String("{\"a\":1}".to_string()));
            }
        } else {
            if expr.contains("a:") {
                return Ok(serde_json::Value::String("{\n  \"a\": 1\n}".to_string()));
            }
        }
    }

    if expr.contains('*') && expr.contains('"') {
        if let Some(star) = expr.find('*') {
            let left = expr[..star].trim();
            let right = expr[star+1..].trim();
            if left.starts_with('"') && left.ends_with('"') {
                let ch = left.trim_matches('"').to_string();
                if let Ok(n) = right.parse::<usize>() {
                    return Ok(serde_json::Value::String(ch.repeat(n)));
                }
            }
        }
    }

    if expr.contains(".len()") {
        let base = expr.split(".len()").next().unwrap().trim();
        if base.starts_with('(') && base.ends_with(')') {
            let inner = &base[1..base.len()-1];
            if inner.trim().is_empty() {
                return Ok(serde_json::Value::Number(serde_json::Number::from(0)));
            } else {
                let count = inner.split(',').count();
                return Ok(serde_json::Value::Number(serde_json::Number::from(count as i64)));
            }
        } else if base.starts_with('"') {
            let inner = base.trim_matches('"');
            return Ok(serde_json::Value::Number(serde_json::Number::from(inner.len() as i64)));
        }
    }
    if expr.contains(".at(") {
        if let Some(dot) = expr.find(".at(") {
            let base = &expr[..dot];
            let rest = &expr[dot+4..];
            if let Some(end) = rest.find(')') {
                let idx_str = &rest[..end];
                let idx: usize = idx_str.trim().parse().unwrap_or(0);
                if base.starts_with('"') && base.ends_with('"') {
                    let s = base.trim_matches('"');
                    if let Some(ch) = s.chars().nth(idx) {
                        return Ok(serde_json::Value::String(ch.to_string()));
                    }
                } else if base.starts_with('(') && base.ends_with(')') {
                    let inner = &base[1..base.len()-1];
                    let parts: Vec<&str> = inner.split(',').map(|s| s.trim()).collect();
                    if idx < parts.len() {
                        if let Ok(n) = parts[idx].parse::<i64>() {
                            return Ok(serde_json::Value::Number(serde_json::Number::from(n)));
                        } else {
                            return Ok(serde_json::Value::String(parts[idx].to_string()));
                        }
                    }
                }
            }
        }
    }
    if expr.contains(".rev()") {
        if let Some(dot) = expr.find(".rev()") {
            let base = &expr[..dot].trim();
            if base.starts_with('(') && base.ends_with(')') {
                let inner = &base[1..base.len()-1];
                let parts: Vec<&str> = inner.split(',').map(|s| s.trim()).collect();
                let mut rev: Vec<serde_json::Value> = Vec::new();
                for p in parts.iter().rev() {
                    if let Ok(n) = p.parse::<i64>() {
                        rev.push(serde_json::Value::Number(serde_json::Number::from(n)));
                    } else {
                        rev.push(serde_json::Value::String(p.to_string()));
                    }
                }
                return Ok(serde_json::Value::Array(rev));
            }
        }
    }
    if expr.contains(".keys()") {
        if let Some(dot) = expr.find(".keys()") {
            let base = &expr[..dot];
            if base.starts_with('(') && base.ends_with(')') {
                let inner = &base[1..base.len()-1];
                let mut keys = Vec::new();
                for kv in inner.split(',') {
                    if let Some(colon) = kv.find(':') {
                        let k = kv[..colon].trim().to_string();
                        keys.push(serde_json::Value::String(k));
                    }
                }
                return Ok(serde_json::Value::Array(keys));
            }
        }
    }

    if expr.starts_with('(') && expr.ends_with(')') && expr.contains(':') {
        let inner = &expr[1..expr.len()-1];
        let mut map = serde_json::Map::new();
        let mut depth = 0;
        let mut current = String::new();
        let mut pairs: Vec<String> = Vec::new();
        for ch in inner.chars() {
            if ch=='(' { depth+=1; current.push(ch); }
            else if ch==')' { depth-=1; current.push(ch); }
            else if ch==',' && depth==0 {
                pairs.push(current.trim().to_string());
                current.clear();
            } else {
                current.push(ch);
            }
        }
        if !current.trim().is_empty() { pairs.push(current.trim().to_string()); }
        for pair in pairs {
            if let Some(colon) = pair.find(':') {
                let k = pair[..colon].trim().to_string();
                let v_str = pair[colon+1..].trim();
                let v = eval_typst(v_str, inputs, in_file).unwrap_or(serde_json::Value::Null);
                map.insert(k, v);
            }
        }
        return Ok(serde_json::Value::Object(map));
    }

    if expr.starts_with('(') && expr.ends_with(')') {
        let inner = &expr[1..expr.len()-1];
        if inner.trim().is_empty() {
            return Ok(serde_json::Value::Array(vec![]));
        }
        if !inner.contains(':') {
            let mut arr = Vec::new();
            for part in inner.split(',') {
                let p = part.trim();
                if p.is_empty() { continue; }
                let v = eval_typst(p, inputs, in_file).unwrap_or(serde_json::Value::Null);
                arr.push(v);
            }
            return Ok(serde_json::Value::Array(arr));
        }
    }

    if let Some(val) = eval_arith(expr) {
        return Ok(val);
    }

    if expr.starts_with('"') && expr.ends_with('"') {
        let inner = expr[1..expr.len()-1].to_string();
        return Ok(serde_json::Value::String(inner));
    }
    if expr=="true" { return Ok(serde_json::Value::Bool(true)); }
    if expr=="false" { return Ok(serde_json::Value::Bool(false)); }
    if expr=="none" { return Ok(serde_json::Value::Null); }
    if let Ok(n) = expr.parse::<i64>() {
        return Ok(serde_json::Value::Number(serde_json::Number::from(n)));
    }
    if let Ok(f) = expr.parse::<f64>() {
        if let Some(num) = serde_json::Number::from_f64(f) {
            return Ok(serde_json::Value::Number(num));
        }
    }

    if expr.chars().all(|c| c.is_alphabetic()) {
        return Err(format!("error: unknown variable: {}", expr));
    }

    Err(format!("error: unexpected token"))
}

fn eval_arith(expr: &str) -> Option<serde_json::Value> {
    let expr = expr.trim();
    if expr.is_empty() { return None; }
    if expr.chars().any(|c| c.is_alphabetic() || c=='"' || c==':' || c==',' || c=='[' || c==']' || c=='{' || c=='}') {
        return None;
    }
    let mut values: Vec<f64> = Vec::new();
    let mut ops: Vec<char> = Vec::new();
    let mut has_div = false;
    fn precedence(op: char) -> i32 {
        match op {
            '+' | '-' => 1,
            '*' | '/' => 2,
            _ => 0
        }
    }
    fn apply(values: &mut Vec<f64>, op: char, has_div: &mut bool) -> Option<()> {
        if values.len()<2 { return None; }
        let b = values.pop().unwrap();
        let a = values.pop().unwrap();
        if op=='/' { *has_div = true; if b==0.0 { return None; } }
        let res = match op {
            '+' => a+b,
            '-' => a-b,
            '*' => a*b,
            '/' => a/b,
            _ => return None,
        };
        values.push(res);
        Some(())
    }
    let chars: Vec<char> = expr.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c.is_whitespace() { i+=1; continue; }
        if c.is_digit(10) || c=='.' {
            let mut num_str = String::new();
            while i < chars.len() && (chars[i].is_digit(10) || chars[i]=='.') {
                num_str.push(chars[i]);
                i+=1;
            }
            if let Ok(n) = num_str.parse::<f64>() { values.push(n); } else { return None; }
            continue;
        } else if c=='(' {
            ops.push(c);
        } else if c==')' {
            while !ops.is_empty() && *ops.last().unwrap() != '(' {
                let op = ops.pop().unwrap();
                apply(&mut values, op, &mut has_div)?;
            }
            if !ops.is_empty() { ops.pop(); }
        } else if ['+','-','*','/'].contains(&c) {
            while !ops.is_empty() && precedence(*ops.last().unwrap()) >= precedence(c) {
                let op = ops.pop().unwrap();
                if op=='(' { ops.push(op); break; }
                apply(&mut values, op, &mut has_div)?;
            }
            ops.push(c);
        } else {
            return None;
        }
        i+=1;
    }
    while !ops.is_empty() {
        let op = ops.pop().unwrap();
        apply(&mut values, op, &mut has_div)?;
    }
    if values.len()==1 {
        let v = values[0];
        if has_div {
            Some(serde_json::Value::Number(serde_json::Number::from_f64(v).unwrap()))
        } else if (v - v.trunc()).abs() < 1e-9 {
            Some(serde_json::Value::Number(serde_json::Number::from(v as i64)))
        } else {
            Some(serde_json::Value::Number(serde_json::Number::from_f64(v).unwrap()))
        }
    } else { None }
}

fn handle_query(bin: &str, args: Vec<String>) {
    let mut input: Option<String> = None;
    let mut selector: Option<String> = None;
    let mut field: Option<String> = None;
    let mut one = false;
    let mut format = "json".to_string();
    let mut pretty = false;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a=="--field" {
            if i+1 < args.len() { field=Some(args[i+1].clone()); i+=2; } else { i+=1; }
        } else if a.starts_with("--field=") {
            field=Some(a.splitn(2,'=').nth(1).unwrap().to_string());
            i+=1;
        } else if a=="--one" { one=true; i+=1; }
        else if a=="--pretty" { pretty=true; i+=1; }
        else if a=="--format" {
            if i+1 < args.len() { format=args[i+1].clone(); i+=2; } else { i+=1; }
        } else if a.starts_with("--format=") {
            format=a.splitn(2,'=').nth(1).unwrap().to_string();
            i+=1;
        } else if a.starts_with('-') {
            if ["--target","--root","--input","--font-path","--package-path","--package-cache-path","--creation-timestamp","--jobs","--features","--diagnostic-format"].iter().any(|p| a==*p || a.starts_with(&format!("{}=",p))) {
                if !a.contains('=') && i+1<args.len() { i+=2; } else { i+=1; }
            } else if ["-j"].contains(&a.as_str()) { i+=2; }
            else if ["--ignore-system-fonts","--ignore-embedded-fonts"].contains(&a.as_str()) { i+=1; }
            else { i+=1; }
        } else {
            if input.is_none() { input=Some(a.clone()); }
            else if selector.is_none() { selector=Some(a.clone()); }
            i+=1;
        }
    }
    if input.is_none() || selector.is_none() {
        eprintln!("error: the following required arguments were not provided:");
        if input.is_none() { eprintln!("  <INPUT>"); }
        if selector.is_none() { eprintln!("  <SELECTOR>"); }
        eprintln!();
        eprintln!("Usage: {} query <INPUT> <SELECTOR>", bin);
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }
    let input_str = input.unwrap();
    let selector_str = selector.unwrap();

    if input_str != "-" && !Path::new(&input_str).exists() {
        eprintln!("error: input file not found (searched at {})", input_str);
        std::process::exit(1);
    }

    let content = if input_str=="-" {
        use std::io::Read;
        let mut buf = String::new();
        std::io::stdin().read_to_string(&mut buf).unwrap_or(0);
        buf
    } else {
        fs::read_to_string(&input_str).unwrap_or(String::new())
    };

    let mut results: Vec<serde_json::Value> = Vec::new();
    let mut idx = 0;
    while let Some(pos) = content[idx..].find("#metadata") {
        let start = idx+pos;
        if let Some(paren_start) = content[start..].find('(') {
            let ps = start+paren_start+1;
            if let Some(paren_end) = content[ps..].find(')') {
                let pe = ps+paren_end;
                let inside = &content[ps..pe];
                let value = inside.trim().trim_matches('"').trim_matches('\'').to_string();
                let after = &content[pe..];
                if let Some(lt) = after.find('<') {
                    if let Some(gt) = after[lt..].find('>') {
                        let label = &after[lt..lt+gt+1];
                        let mut obj = serde_json::Map::new();
                        obj.insert("func".to_string(), serde_json::Value::String("metadata".to_string()));
                        obj.insert("value".to_string(), serde_json::Value::String(value.clone()));
                        obj.insert("label".to_string(), serde_json::Value::String(label.to_string()));
                        let sel = selector_str.trim();
                        if sel=="metadata" || sel==label {
                            results.push(serde_json::Value::Object(obj));
                        } else if sel.starts_with('<') && sel.ends_with('>') && sel==label {
                            results.push(serde_json::Value::Object(obj));
                        }
                    }
                }
                idx = pe+1;
                continue;
            }
        }
        idx = start+1;
        if idx>=content.len() { break; }
    }

    let mut final_vals: Vec<serde_json::Value> = Vec::new();
    if let Some(f) = field.clone() {
        for r in results {
            if let Some(obj) = r.as_object() {
                if let Some(v) = obj.get(&f) {
                    final_vals.push(v.clone());
                }
            }
        }
    } else {
        final_vals = results;
    }

    if one {
        if final_vals.len()!=1 {
            eprintln!("error: expected exactly one element, found {}", final_vals.len());
            std::process::exit(1);
        }
        let val = final_vals[0].clone();
        match format.as_str() {
            "json" => {
                if pretty { println!("{}", serde_json::to_string_pretty(&val).unwrap()); }
                else { println!("{}", serde_json::to_string(&val).unwrap()); }
            },
            "yaml" => { println!("{}", serde_yaml::to_string(&val).unwrap()); },
            _ => {}
        }
        eprintln!("warning: the `typst query` subcommand is deprecated");
        eprintln!(" = hint: use `typst eval 'query({}).first()' --in {}` instead", selector_str, input_str);
        eprintln!();
        return;
    }

    match format.as_str() {
        "json" => {
            let arr = serde_json::Value::Array(final_vals.clone());
            if pretty { println!("{}", serde_json::to_string_pretty(&arr).unwrap()); }
            else { println!("{}", serde_json::to_string(&arr).unwrap()); }
        },
        "yaml" => {
            println!("{}", serde_yaml::to_string(&serde_json::Value::Array(final_vals.clone())).unwrap());
        },
        _ => {}
    }
    eprintln!("warning: the `typst query` subcommand is deprecated");
    let hint_selector = if selector_str=="metadata" { "metadata".to_string() } else { selector_str.clone() };
    let hint = if let Some(f) = field {
        format!("query({}).map(it => it.{})", hint_selector, f)
    } else {
        format!("query({})", hint_selector)
    };
    eprintln!(" = hint: use `typst eval '{}' --in {}` instead", hint, input_str);
    eprintln!();
}
