fn suggest_similar(input: &str, candidates: &[&str]) -> Option<String> {
    fn lev(a: &str, b: &str) -> usize {
        let mut dp = vec![vec![0; b.len()+1]; a.len()+1];
        for i in 0..=a.len() { dp[i][0]=i; }
        for j in 0..=b.len() { dp[0][j]=j; }
        for (i, ca) in a.chars().enumerate() {
            for (j, cb) in b.chars().enumerate() {
                let cost = if ca==cb {0} else {1};
                dp[i+1][j+1] = std::cmp::min(
                    std::cmp::min(dp[i][j+1]+1, dp[i+1][j]+1),
                    dp[i][j]+cost
                );
            }
        }
        dp[a.len()][b.len()]
    }
    let mut best: Option<(usize,String)> = None;
    for c in candidates {
        let d = lev(input, c);
        if d<=3 {
            if best.is_none() || d < best.as_ref().unwrap().0 {
                best = Some((d, c.to_string()));
            }
        }
    }
    best.map(|(_,s)| s)
}

fn path_relative_from(path: &Path, base: &Path) -> Option<String> {
    let p_str = path.to_string_lossy().to_string();
    let b_str = base.to_string_lossy().to_string();
    let p_parts: Vec<String> = p_str.split('/').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect();
    let b_parts: Vec<String> = b_str.split('/').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect();
    let mut common = 0;
    for (x,y) in p_parts.iter().zip(b_parts.iter()) {
        if x==y { common+=1; } else { break; }
    }
    let up = b_parts.len() - common;
    let mut rel_parts = Vec::new();
    for _ in 0..up { rel_parts.push("..".to_string()); }
    rel_parts.extend(p_parts[common..].iter().cloned());
    if rel_parts.is_empty() { return Some(".".to_string()); }
    Some(rel_parts.join("/"))
}

