fn lorem_n(n: usize) -> String {
    let words = get_lorem_words();
    if n==0 { return "".to_string(); }
    let mut selected: Vec<String> = words.iter().take(n).cloned().collect();
    if let Some(last) = selected.last_mut() {
        if last.ends_with(',') {
            let mut chars: Vec<char> = last.chars().collect();
            if let Some(pos) = chars.iter().rposition(|&c| c==',') {
                chars[pos] = '.';
                *last = chars.into_iter().collect();
            }
        } else if !last.ends_with('.') && !last.ends_with('!') && !last.ends_with('?') && !last.ends_with(';') && !last.ends_with(':') {
            last.push('.');
        }
    }
    selected.join(" ")
}

