            platform.insert("arch".to_string(), serde_json::Value::String("x86_64".to_string()));
            build.insert("platform".to_string(), serde_json::Value::Object(platform));
            let mut settings = serde_json::Map::new();
            settings.insert("self-update".to_string(), serde_json::Value::Bool(false));
            settings.insert("http-server".to_string(), serde_json::Value::Bool(true));
            build.insert("settings".to_string(), serde_json::Value::Object(settings));
            obj.insert("build".to_string(), serde_json::Value::Object(build));
            let mut features = serde_json::Map::new();
            features.insert("html".to_string(), serde_json::Value::Bool(false));
            features.insert("a11y-extras".to_string(), serde_json::Value::Bool(false));
            obj.insert("features".to_string(), serde_json::Value::Object(features));
            let mut fonts = serde_json::Map::new();
            let paths_json: Vec<serde_json::Value> = font_paths.iter().map(|p| serde_json::Value::String(p.clone())).collect();
            fonts.insert("paths".to_string(), serde_json::Value::Array(paths_json));
            fonts.insert("system".to_string(), serde_json::Value::Bool(system_fonts));
            fonts.insert("embedded".to_string(), serde_json::Value::Bool(embedded_fonts));
            obj.insert("fonts".to_string(), serde_json::Value::Object(fonts));
            let mut packages = serde_json::Map::new();
            packages.insert("package-path".to_string(), serde_json::Value::String(package_path));
            packages.insert("package-cache-path".to_string(), serde_json::Value::String(package_cache_path));
            obj.insert("packages".to_string(), serde_json::Value::Object(packages));
            obj.insert("env".to_string(), serde_json::Value::Object(env_json));
            let json_val = serde_json::Value::Object(obj);
            if pretty {
                println!("{}", serde_json::to_string_pretty(&json_val).unwrap());
            } else {
                println!("{}", serde_json::to_string(&json_val).unwrap());
            }
        },
        Some("yaml") => {
            println!("version: 0.14.2");
