            println!("env:");
            for k in env_vars.iter() {
                if let Some(v) = env_map.get(*k).unwrap() {
                    println!("  {}: {}", k, v);
                } else {
                    println!("  {}: null", k);
                }
            }
            println!();
        },
        None => {
            println!("Version 0.14.2 (97ac4370, linux on x86_64)");
            println!();
            println!("Build settings");
            println!("  self-update off (Update Typst via `typst update`)");
            println!("  http-server on  (Serve HTML via `typst watch`)");
